/**  任务从哪下载东西（下载历史按它筛选） */
export type JobSource = 
/**  游戏本体、加载器 */
"game" | "java" | "modrinth" | "curseForge" | 
/**  本地文件：拖进来的、导入的整合包、世界备份、导出、复制实例 */
"local" | "other";

export type JobState = "running" | "paused" | "succeeded" | "failed" | "cancelled" | 
/**  启动器关掉时还没做完（只出现在以前的历史里） */
"interrupted";

/**  做过的一步 */
export type JobStep = {
	label: string,
	/**  开始这一步的时间（毫秒级 Unix 时间戳） */
	at: number | null,
};

/**  某个任务的状态或进度变了（核心库已做节流）。 */
export type JobUpdated = JobSnapshot;

/**  启动时官验失败。保留原请求供界面在用户决定后重试。 */
export type LaunchAuthBlocked = {
	instanceId: string,
	world: string | null,
	serverAddress: string | null,
	memoryMb: number | null,
	code: string,
	message: string,
};

/**  启动钩子命令（在游戏启动前与退出后运行） */
